-- Commercial returns leave PO fulfilment unchanged and record supplier credits
-- independently from immutable invoices and the original cash payments.
ALTER TABLE purchase_bills ADD COLUMN credit_total numeric(18,2) NOT NULL DEFAULT 0 CHECK(credit_total>=0 AND credit_total<=total);
DO $$
DECLARE constraint_name text;
BEGIN
    -- PostgreSQL names this cross-column check purchase_bills_checkN. Match its
    -- definition rather than relying on an autogenerated name or its ordinal.
    FOR constraint_name IN SELECT conname FROM pg_constraint
        WHERE conrelid='purchase_bills'::regclass AND contype='c'
        AND pg_get_constraintdef(oid) LIKE '%paid%'
        AND pg_get_constraintdef(oid) NOT LIKE '%status%'
    LOOP EXECUTE format('ALTER TABLE purchase_bills DROP CONSTRAINT %I',constraint_name); END LOOP;
END $$;
ALTER TABLE purchase_bills ADD CONSTRAINT purchase_bills_paid_credit_check CHECK(paid>=0 AND paid<=total-credit_total);
ALTER TABLE purchase_bills DROP CONSTRAINT purchase_bills_paid_status_check;
ALTER TABLE purchase_bills ADD CONSTRAINT purchase_bills_paid_status_check CHECK(
    (status='unpaid' AND paid=0 AND total-credit_total>0) OR (status='partial' AND paid>0 AND paid<total-credit_total)
    OR (status='paid' AND paid=total-credit_total) OR (status='void' AND paid=0 AND credit_total=0));
CREATE OR REPLACE FUNCTION guard_purchase_bill_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.status='void' OR NEW.version<>OLD.version+1
        OR (to_jsonb(NEW)-'status'-'paid'-'version'-'credit_total') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'paid'-'version'-'credit_total')
        OR (NEW.status='void' AND (OLD.paid<>0 OR OLD.credit_total<>0)) THEN
        RAISE EXCEPTION 'Posted bill financial details are immutable; correct dependent payments and returns first';
    END IF;
    RETURN NEW;
END $$;
DO $$
DECLARE variance_code text;
BEGIN
 SELECT n::text INTO variance_code FROM generate_series(5900,5999) n
 WHERE NOT EXISTS(SELECT 1 FROM accounts WHERE code=n::text) ORDER BY n LIMIT 1;
 IF variance_code IS NULL THEN
  WITH candidates AS (SELECT 1000000000::bigint n UNION SELECT code::bigint+1 FROM accounts WHERE code~'^[1-9][0-9]{9}$' AND code<>'9999999999')
  SELECT min(n)::text INTO variance_code FROM candidates WHERE NOT EXISTS(SELECT 1 FROM accounts WHERE code=n::text);
 END IF;
 IF variance_code IS NULL THEN RAISE EXCEPTION 'No unused purchase return variance account code'; END IF;
 INSERT INTO accounts(code,name,kind,system_role) VALUES(variance_code,'Selisih nilai retur pembelian','expense','purchase_return_variance');
END $$;
ALTER TABLE journal_entries DROP CONSTRAINT journal_entries_source_type_check;
ALTER TABLE journal_entries ADD CONSTRAINT journal_entries_source_type_check CHECK(source_type IN
 ('receipt','shipment','invoice','payment','manual','adjustment','reversal','opening','purchase_receipt','purchase_bill','supplier_payment','supplier_return'));
ALTER TABLE posting_reversals DROP CONSTRAINT posting_reversals_source_type_check;
ALTER TABLE posting_reversals ADD CONSTRAINT posting_reversals_source_type_check CHECK(source_type IN
 ('payment','invoice','shipment','opening','manual','receipt','purchase_receipt','purchase_bill','supplier_payment','supplier_return'));
ALTER TABLE inventory_movements DROP CONSTRAINT inventory_movements_kind_check;
ALTER TABLE inventory_movements ADD CONSTRAINT inventory_movements_kind_check CHECK(kind IN
 ('receipt','shipment','adjustment','shipment_reversal','opening','opening_reversal','receipt_reversal','purchase_receipt','purchase_receipt_reversal','supplier_return','supplier_return_reversal'));
ALTER TABLE inventory_movements DROP CONSTRAINT inventory_movements_direction_check;
ALTER TABLE inventory_movements ADD CONSTRAINT inventory_movements_direction_check CHECK(
 (kind IN ('receipt','shipment_reversal','opening','purchase_receipt','supplier_return_reversal') AND quantity>0) OR
 (kind IN ('shipment','opening_reversal','receipt_reversal','purchase_receipt_reversal','supplier_return') AND quantity<0) OR
 (kind='adjustment' AND quantity<>0));
CREATE SEQUENCE supplier_return_number;
CREATE TABLE supplier_returns(
 id uuid PRIMARY KEY,number text NOT NULL UNIQUE,bill_id uuid NOT NULL REFERENCES purchase_bills(id),
 credit_total numeric(18,2) NOT NULL CHECK(credit_total>0),inventory_value numeric(18,2) NOT NULL CHECK(inventory_value>=0),
 refund numeric(18,2) NOT NULL CHECK(refund>=0 AND refund<=credit_total),
 reason text NOT NULL CHECK(char_length(reason) BETWEEN 3 AND 1000),
 journal_id uuid NOT NULL UNIQUE REFERENCES journal_entries(id),created_by uuid NOT NULL REFERENCES users(id),
 created_at timestamptz NOT NULL DEFAULT now(),posting_transaction xid8 NOT NULL DEFAULT pg_current_xact_id());
CREATE INDEX supplier_returns_bill_idx ON supplier_returns(bill_id,created_at,id);
ALTER TABLE inventory_movements ADD COLUMN supplier_return_id uuid REFERENCES supplier_returns(id);
ALTER TABLE inventory_movements ADD CONSTRAINT supplier_return_reference_check CHECK(
 (kind IN ('supplier_return','supplier_return_reversal') AND supplier_return_id IS NOT NULL) OR
 (kind NOT IN ('supplier_return','supplier_return_reversal') AND supplier_return_id IS NULL));
CREATE TABLE supplier_return_lines(
 id uuid PRIMARY KEY,return_id uuid NOT NULL REFERENCES supplier_returns(id),bill_line_id uuid NOT NULL REFERENCES purchase_bill_lines(id),
 movement_id uuid NOT NULL UNIQUE REFERENCES inventory_movements(id),position integer NOT NULL CHECK(position BETWEEN 1 AND 100),
 product_id uuid NOT NULL REFERENCES products(id),product_sku text NOT NULL,product_name text NOT NULL,unit text NOT NULL,
 quantity numeric(18,3) NOT NULL CHECK(quantity>0),credit numeric(18,2) NOT NULL CHECK(credit>0),
 value numeric(18,2) NOT NULL CHECK(value>=0),unit_cost numeric(18,4) NOT NULL CHECK(unit_cost>=0),
 before_quantity numeric(18,3) NOT NULL,before_value numeric(18,2) NOT NULL,before_average numeric(18,4) NOT NULL,
 UNIQUE(return_id,bill_line_id),UNIQUE(return_id,position));
CREATE INDEX supplier_return_lines_source_idx ON supplier_return_lines(bill_line_id);
CREATE TRIGGER immutable_supplier_returns BEFORE UPDATE OR DELETE ON supplier_returns FOR EACH ROW EXECUTE FUNCTION immutable_posting();
CREATE TRIGGER immutable_supplier_returns_truncate BEFORE TRUNCATE ON supplier_returns FOR EACH STATEMENT EXECUTE FUNCTION immutable_posting();
CREATE TRIGGER immutable_supplier_return_lines BEFORE UPDATE OR DELETE ON supplier_return_lines FOR EACH ROW EXECUTE FUNCTION immutable_posting();
CREATE TRIGGER immutable_supplier_return_lines_truncate BEFORE TRUNCATE ON supplier_return_lines FOR EACH STATEMENT EXECUTE FUNCTION immutable_posting();
CREATE FUNCTION guard_supplier_return_append() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE current_transaction xid8:=pg_current_xact_id();
BEGIN
 IF NOT EXISTS(SELECT 1 FROM supplier_returns r JOIN purchase_bill_lines b ON b.id=NEW.bill_line_id
 WHERE r.id=NEW.return_id AND r.bill_id=b.bill_id AND r.posting_transaction=current_transaction
 AND r.xmin::text::numeric=mod(current_transaction::text::numeric,4294967296)) THEN
 RAISE EXCEPTION 'Cannot append lines to a posted supplier return'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_supplier_return_lines BEFORE INSERT ON supplier_return_lines FOR EACH ROW EXECUTE FUNCTION guard_supplier_return_append();
CREATE FUNCTION supplier_bill_returned_quantity(bill_line uuid) RETURNS numeric LANGUAGE sql STABLE AS $$
 SELECT COALESCE(sum(l.quantity),0) FROM supplier_return_lines l JOIN supplier_returns r ON r.id=l.return_id
 WHERE l.bill_line_id=bill_line AND NOT EXISTS(SELECT 1 FROM posting_reversals v WHERE v.source_type='supplier_return' AND v.source_id=r.id)
$$;
CREATE FUNCTION supplier_bill_returned_credit(bill_line uuid) RETURNS numeric LANGUAGE sql STABLE AS $$
 SELECT COALESCE(sum(l.credit),0) FROM supplier_return_lines l JOIN supplier_returns r ON r.id=l.return_id
 WHERE l.bill_line_id=bill_line AND NOT EXISTS(SELECT 1 FROM posting_reversals v WHERE v.source_type='supplier_return' AND v.source_id=r.id)
$$;
CREATE FUNCTION supplier_return_blocked_reason(target uuid) RETURNS text LANGUAGE sql STABLE AS $$
 SELECT CASE
 WHEN EXISTS(SELECT 1 FROM posting_reversals WHERE source_type='supplier_return' AND source_id=r.id) THEN 'Retur supplier sudah dibalik.'
 WHEN b.status='void' THEN 'Tagihan supplier tidak aktif.'
 WHEN EXISTS(SELECT 1 FROM supplier_return_lines l JOIN inventory_movements m ON m.id=l.movement_id WHERE l.return_id=r.id
   AND EXISTS(SELECT 1 FROM inventory_movements later WHERE later.product_id=l.product_id AND later.movement_seq>m.movement_seq))
 THEN 'Ada mutasi stok setelah retur; saldo historis tidak dapat diputar ulang.'
 WHEN EXISTS(SELECT 1 FROM supplier_return_lines l JOIN products p ON p.id=l.product_id WHERE l.return_id=r.id
   AND (p.quantity<>l.before_quantity-l.quantity OR p.inventory_value<>l.before_value-l.value OR
     p.average_cost<>CASE WHEN l.before_quantity=l.quantity THEN 0 ELSE l.before_average END))
 THEN 'Saldo stok tidak cocok dengan snapshot retur.'
 WHEN r.refund>(SELECT COALESCE(sum(debit-credit),0) FROM journal_lines WHERE account_code='1100') THEN 'Kas tidak cukup untuk membalik pengembalian dana supplier.'
 WHEN NOT(SELECT closed_through IS NULL OR (now() AT TIME ZONE (SELECT timezone FROM company))::date>closed_through FROM accounting_period WHERE singleton)
 THEN 'Periode akuntansi saat ini sudah ditutup.'
 ELSE NULL END FROM supplier_returns r JOIN purchase_bills b ON b.id=r.bill_id WHERE r.id=target
$$;
CREATE FUNCTION supplier_return_history(target uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',r.id,'number',r.number,'bill_id',r.bill_id,'credit_total',r.credit_total::text,
 'inventory_value',r.inventory_value::text,'refund',r.refund::text,'reason',r.reason,'journal_id',r.journal_id,'created_at',r.created_at,
 'can_reverse',supplier_return_blocked_reason(r.id) IS NULL,'reversal_blocked_reason',supplier_return_blocked_reason(r.id),
 'reversal',CASE WHEN v.id IS NULL THEN NULL ELSE jsonb_build_object('id',v.id,'reason',v.reason,'created_at',v.created_at,'journal_id',j.id) END,
 'items',(SELECT jsonb_agg(jsonb_build_object('id',l.id,'bill_line_id',l.bill_line_id,'product_id',l.product_id,'product_sku',l.product_sku,
 'product_name',l.product_name,'unit',l.unit,'quantity',l.quantity::text,'credit',l.credit::text,'value',l.value::text)
 ORDER BY l.position) FROM supplier_return_lines l WHERE l.return_id=r.id)) ORDER BY r.created_at,r.id),'[]'::jsonb)
 FROM supplier_returns r LEFT JOIN posting_reversals v ON v.source_type='supplier_return' AND v.source_id=r.id
 LEFT JOIN journal_entries j ON j.source_type='reversal' AND j.source_id=v.id WHERE r.bill_id=target
$$;
CREATE OR REPLACE FUNCTION purchase_bill_blocked_reason(bill uuid) RETURNS text LANGUAGE sql STABLE AS $$
 SELECT CASE WHEN b.status='void' THEN 'Tagihan supplier sudah dibalik.'
 WHEN b.credit_total>0 THEN 'Balikkan seluruh retur aktif sebelum membatalkan tagihan.'
 WHEN b.paid>0 THEN 'Balikkan seluruh pembayaran aktif sebelum membatalkan tagihan.'
 WHEN NOT (SELECT closed_through IS NULL OR (now() AT TIME ZONE (SELECT timezone FROM company))::date>closed_through FROM accounting_period WHERE singleton)
 THEN 'Periode akuntansi saat ini sudah ditutup.' ELSE NULL END FROM purchase_bills b WHERE b.id=bill
$$;
